/**
 * Type guard utilities for Zalo SDK webhook events
 * 
 * This file provides type-safe functions to check webhook event types
 * and narrow down TypeScript types for better development experience.
 */

import {
  WebhookEvent,
  GroupWebhookEvent,
  OAMessageWebhookEvent,
  UserMessageWebhookEvent,
  UserSendGroupTextEvent,
  UserSendGroupImageEvent,
  UserSendGroupVideoEvent,
  UserSendGroupAudioEvent,
  UserSendGroupFileEvent,
  OASendTextEvent,
  OASendImageEvent,
  OASendFileEvent,
  OASendStickerEvent,
  OASendGifEvent,
  OASendGroupTextEvent,
  OASendGroupImageEvent,
  OASendGroupFileEvent,
  OASendGroupStickerEvent,
  OASendGroupGifEvent,
  WebhookEventName,
} from '../types/webhook';

// ===== USER GROUP MESSAGE TYPE GUARDS =====

/**
 * Type union for user message events in groups
 */
export type UserGroupMessageEvent =
  | UserSendGroupTextEvent
  | UserSendGroupImageEvent
  | UserSendGroupVideoEvent
  | UserSendGroupAudioEvent
  | UserSendGroupFileEvent;

/**
 * Check if event is a user sending text message to group
 */
export function isUserSendGroupTextEvent(
  event: WebhookEvent
): event is UserSendGroupTextEvent {
  return event.event_name === WebhookEventName.USER_SEND_GROUP_TEXT;
}

/**
 * Check if event is a user sending image message to group
 */
export function isUserSendGroupImageEvent(
  event: WebhookEvent
): event is UserSendGroupImageEvent {
  return event.event_name === WebhookEventName.USER_SEND_GROUP_IMAGE;
}

/**
 * Check if event is a user sending video message to group
 */
export function isUserSendGroupVideoEvent(
  event: WebhookEvent
): event is UserSendGroupVideoEvent {
  return event.event_name === WebhookEventName.USER_SEND_GROUP_VIDEO;
}

/**
 * Check if event is a user sending audio message to group
 */
export function isUserSendGroupAudioEvent(
  event: WebhookEvent
): event is UserSendGroupAudioEvent {
  return event.event_name === WebhookEventName.USER_SEND_GROUP_AUDIO;
}

/**
 * Check if event is a user sending file to group
 */
export function isUserSendGroupFileEvent(
  event: WebhookEvent
): event is UserSendGroupFileEvent {
  return event.event_name === WebhookEventName.USER_SEND_GROUP_FILE;
}

/**
 * Check if event is any user group message event
 */
export function isUserGroupMessageEvent(
  event: WebhookEvent
): event is UserGroupMessageEvent {
  return [
    WebhookEventName.USER_SEND_GROUP_TEXT,
    WebhookEventName.USER_SEND_GROUP_IMAGE,
    WebhookEventName.USER_SEND_GROUP_VIDEO,
    WebhookEventName.USER_SEND_GROUP_AUDIO,
    WebhookEventName.USER_SEND_GROUP_FILE,
  ].includes(event.event_name as WebhookEventName);
}

