// ===== COMBINED TYPE GUARDS =====

/**
 * Check if event is any OA message event (personal or group)
 */
export function isOAMessageEvent(
  event: WebhookEvent
): event is OAMessageWebhookEvent {
  return [
    WebhookEventName.OA_SEND_TEXT,
    WebhookEventName.OA_SEND_IMAGE,
    WebhookEventName.OA_SEND_FILE,
    WebhookEventName.OA_SEND_STICKER,
    WebhookEventName.OA_SEND_GIF,
    WebhookEventName.OA_SEND_GROUP_TEXT,
    WebhookEventName.OA_SEND_GROUP_IMAGE,
    WebhookEventName.OA_SEND_GROUP_FILE,
    WebhookEventName.OA_SEND_GROUP_STICKER,
    WebhookEventName.OA_SEND_GROUP_GIF,
  ].includes(event.event_name as WebhookEventName);
}

/**
 * Check if event is any user message event (personal or group)
 */
export function isUserMessageEvent(
  event: WebhookEvent
): event is UserMessageWebhookEvent {
  return [
    WebhookEventName.USER_SEND_TEXT,
    WebhookEventName.USER_SEND_IMAGE,
    WebhookEventName.USER_SEND_AUDIO,
    WebhookEventName.USER_SEND_VIDEO,
    WebhookEventName.USER_SEND_FILE,
    WebhookEventName.USER_SEND_STICKER,
    WebhookEventName.USER_SEND_LOCATION,
    WebhookEventName.USER_SEND_GROUP_TEXT,
    WebhookEventName.USER_SEND_GROUP_VIDEO,
    WebhookEventName.USER_SEND_GROUP_AUDIO,
    WebhookEventName.USER_SEND_GROUP_FILE,
  ].includes(event.event_name as WebhookEventName);
}

/**
 * Check if event has message attachments
 */
export function hasAttachments(event: WebhookEvent): boolean {
  if ('message' in event && event.message && 'attachments' in event.message) {
    return Array.isArray(event.message.attachments) && event.message.attachments.length > 0;
  }
  return false;
}

/**
 * Check if event is from a group context
 */
export function isFromGroup(event: WebhookEvent): boolean {
  return 'group_id' in event || event.event_name.includes('group');
}

/**
 * Check if event is from a personal context
 */
export function isFromPersonal(event: WebhookEvent): boolean {
  return !isFromGroup(event);
}
