/**
 * Main Zalo SDK class
 */

import { ZaloClient } from "./clients/zalo-client";
import { AuthService } from "./services/auth.service";
import { OAService } from "./services/oa.service";
// import { MessageService } from "./services/message.service"; // Replaced by specialized services
import { UserService } from "./services/user.service";
// import { WebhookService } from "./services/webhook.service";
import { ZNSService } from "./services/zns.service";
import { GroupMessageService } from "./services/group-message.service";
import { GroupManagementService } from "./services/group-management.service";
import { ArticleService } from "./services/article.service";
import { VideoUploadService } from "./services/video-upload.service";

// Message Services
import { ConsultationService } from "./services/consultation.service";
import { TransactionService } from "./services/transaction.service";
import { PromotionService } from "./services/promotion.service";
import { GeneralMessageService } from "./services/general-message.service";
import { MessageManagementService } from "./services/message-management.service";
import { BroadcastService } from "./services/broadcast.service";
import { PurchaseService } from "./services/purchase.service";
// New services from api.md
import { AnonymousMessageService } from "./services/anonymous-message.service";
import { MessageReactionService } from "./services/message-reaction.service";
import { MiniAppMessageService } from "./services/miniapp-message.service";
import {
  ZaloSDKConfig,
  ZaloSDKError,
  Logger,
  ConsoleLogger,
} from "./types/common";
import {
  AccessToken,
  AuthCodeParams,
  RefreshTokenParams,
  SocialUserInfo,
} from "./types/auth";
import { OAInfo, MessageQuota } from "./types/oa";
import { SendMessageResponse } from "./types/message";
import { UserInfo, UserListRequest, UserListResponse } from "./types/user";
// import { WebhookHandlers } from "./types/webhook";

/**
 * Main Zalo SDK class providing access to all Zalo APIs
 */
export class ZaloSDK {
  private readonly client: ZaloClient;
  private readonly logger: Logger;

  // Services
  public readonly auth: AuthService;
  public readonly oa: OAService;
  // public readonly message: MessageService; // Replaced by specialized message services
  public readonly user: UserService;
  // public readonly webhook: WebhookService;
  public readonly zns: ZNSService;
  public readonly groupMessage: GroupMessageService;
  public readonly groupManagement: GroupManagementService;
  public readonly article: ArticleService;
  public readonly videoUpload: VideoUploadService;

  // Message Services - Specialized by message type
  public readonly consultation: ConsultationService;
  public readonly transaction: TransactionService;
  public readonly promotion: PromotionService;
  public readonly generalMessage: GeneralMessageService;
  public readonly messageManagement: MessageManagementService;
  public readonly broadcast: BroadcastService;
  public readonly purchase: PurchaseService;

  // New services from api.md
  public readonly anonymousMessage: AnonymousMessageService;
  public readonly messageReaction: MessageReactionService;
  public readonly miniappMessage: MiniAppMessageService;

  // Configuration
  public readonly config: Required<ZaloSDKConfig>;

  constructor(config: ZaloSDKConfig) {
    // Validate required configuration
    if (!config.appId) {
      throw new ZaloSDKError("appId is required in SDK configuration");
    }
    if (!config.appSecret) {
      throw new ZaloSDKError("appSecret is required in SDK configuration");
    }

    // Set default configuration
    this.config = {
      appId: config.appId,
      appSecret: config.appSecret,
      timeout: config.timeout || 30000,
      debug: config.debug || false,
      apiBaseUrl: config.apiBaseUrl || "https://openapi.zalo.me",
      retry: {
        attempts: config.retry?.attempts || 3,
        delay: config.retry?.delay || 1000,
        ...config.retry,
      },
    };

    this.logger = new ConsoleLogger(this.config.debug);
    this.client = new ZaloClient(this.config);

    // Initialize services
    this.auth = new AuthService(
      this.client,
      this.config.appId,
      this.config.appSecret
    );
    this.oa = new OAService(this.client);
    // this.message = new MessageService(this.client); // Replaced by specialized message services
    this.user = new UserService(this.client);
    // this.webhook = new WebhookService(this.config.appSecret, this.config.debug);
    this.zns = new ZNSService(this.client);
    this.groupMessage = new GroupMessageService(this.client);
    this.groupManagement = new GroupManagementService(this.client);
    this.article = new ArticleService(this.client);
    this.videoUpload = new VideoUploadService(this.client);

    // Initialize message services
    this.consultation = new ConsultationService(this.client);
    this.transaction = new TransactionService(this.client);
    this.promotion = new PromotionService(this.client);
    this.generalMessage = new GeneralMessageService(this.client);
    this.messageManagement = new MessageManagementService(this.client);
    this.broadcast = new BroadcastService(this.client);
    this.purchase = new PurchaseService(this.client);

    // Initialize new services from api.md
    this.anonymousMessage = new AnonymousMessageService(this.client);
    this.messageReaction = new MessageReactionService(this.client);
    this.miniappMessage = new MiniAppMessageService(this.client);

    this.logger.info("Zalo SDK initialized", {
      appId: this.config.appId,
      debug: this.config.debug,
      timeout: this.config.timeout,
    });
  }

  /**
   * Quick method to get OA access token from authorization code
   */
  public async getOAAccessToken(
    code: string,
    redirectUri: string
  ): Promise<AccessToken> {
    const params: AuthCodeParams = {
      app_id: this.config.appId,
      app_secret: this.config.appSecret,
      code,
      redirect_uri: redirectUri,
    };

    return this.auth.getOAAccessToken(params);
  }

  /**
   * Quick method to get Social access token from authorization code
   */
  public async getSocialAccessToken(
    code: string,
    redirectUri: string,
    codeVerifier?: string
  ): Promise<AccessToken> {
    const params: AuthCodeParams = {
      app_id: this.config.appId,
      app_secret: this.config.appSecret,
      code,
      redirect_uri: redirectUri,
      code_verifier: codeVerifier || "",
    };

    return this.auth.getSocialAccessToken(params);
  }

  /**
   * Quick method to refresh OA access token
   */
  public async refreshOAAccessToken(
    refreshToken: string
  ): Promise<AccessToken> {
    const params: RefreshTokenParams = {
      app_id: this.config.appId,
      app_secret: this.config.appSecret,
      refresh_token: refreshToken,
    };

    return this.auth.refreshOAAccessToken(params);
  }

  /**
   * Quick method to refresh Social access token
   */
  public async refreshSocialAccessToken(
    refreshToken: string
  ): Promise<AccessToken> {
    const params: RefreshTokenParams = {
      app_id: this.config.appId,
      app_secret: this.config.appSecret,
      refresh_token: refreshToken,
    };

    return this.auth.refreshSocialAccessToken(params);
  }

  /**
   * Quick method to get OA information
   */
  public async getOAInfo(accessToken: string): Promise<OAInfo> {
    return this.oa.getOAInfo(accessToken);
  }

  /**
   * Quick method to get message quota
   */
  public async getMessageQuota(accessToken: string): Promise<MessageQuota> {
    return this.oa.getMessageQuota(accessToken);
  }

  /**
   * Quick method to get Social user information
   */
  public async getSocialUserInfo(
    accessToken: string,
    fields?: string
  ): Promise<SocialUserInfo> {
    return this.auth.getSocialUserInfo(accessToken, fields);
  }

  /**
   * Quick method to send consultation text message
   */
  public async sendConsultationText(
    accessToken: string,
    userId: string,
    text: string
  ): Promise<SendMessageResponse> {
    return this.consultation.sendTextMessage(
      accessToken,
      { user_id: userId },
      { type: "text", text }
    );
  }

  /**
   * Quick method to get user information
   */
  public async getUserInfo(
    accessToken: string,
    userId: string
  ): Promise<UserInfo> {
    return this.user.getUserInfo(accessToken, userId);
  }

  /**
   * Quick method to get user list
   */
  public async getUserList(
    accessToken: string,
    request: UserListRequest
  ): Promise<UserListResponse> {
    return this.user.getUserList(accessToken, request);
  }

  /**
   * Quick method to get all followers
   */
  public async getFollowers(accessToken: string): Promise<UserListResponse> {
    return this.user.getFollowers(accessToken);
  }

  /**
   * Quick method to register webhook handlers
   */
  // public registerWebhookHandlers(handlers: WebhookHandlers): void {
  //   this.webhook.registerHandlers(handlers);
  // }

  /**
   * Quick method to process webhook
   */
  // public async processWebhook(
  //   payload: string,
  //   signature?: string,
  //   timestamp?: string
  // ): Promise<void> {
  //   return this.webhook.processWebhook(payload, signature, timestamp);
  // }

  /**
   * Create OA authorization URL with PKCE support
   * @deprecated Use auth.createOAAuthUrl() directly for full control over PKCE and state
   */
  public createOAAuthUrl(redirectUri: string, state?: string): string {
    const result = this.auth.createOAAuthUrl(redirectUri, state, undefined, false);
    return result.url;
  }

  /**
   * Create OA authorization URL with full PKCE support
   * Returns both URL and state for enhanced security
   */
  public createSecureOAAuthUrl(redirectUri: string, state?: string, enablePKCE: boolean = true) {
    const result = this.auth.createOAAuthUrl(redirectUri, state, undefined, enablePKCE);
    return result;
  }

  /**
   * Create Social authorization URL
   */
  public createSocialAuthUrl(redirectUri: string, state?: string): string {
    return this.auth.createSocialAuthUrl(redirectUri, state);
  }

  /**
   * Generate PKCE for Social API
   */
  public generatePKCE() {
    return this.auth.generatePKCE();
  }

  /**
   * Validate access token
   */
  public async validateAccessToken(
    accessToken: string,
    scope: "oa" | "social" = "social"
  ): Promise<boolean> {
    try {
      if (scope === "oa") {
        return this.oa.validateOAToken(accessToken);
      } else {
        const validation = await this.auth.validateAccessToken(accessToken);
        return validation.valid;
      }
    } catch (error) {
      this.logger.warn(`Token validation failed: ${(error as Error).message}`);
      return false;
    }
  }

  /**
   * Get SDK version
   */
  public getVersion(): string {
    return "1.0.0";
  }

  /**
   * Get SDK configuration (without sensitive data)
   */
  public getConfig(): Omit<Required<ZaloSDKConfig>, "appSecret"> {
    const { appSecret, ...safeConfig } = this.config;
    return safeConfig;
  }

  /**
   * Enable or disable debug logging
   */
  public setDebug(enabled: boolean): void {
    (this.config as any).debug = enabled;
    // Note: ConsoleLogger debug setting is read-only, create new logger if needed
    if (enabled !== this.config.debug) {
      this.logger.info(`Debug mode ${enabled ? "enabled" : "disabled"}`);
    }
  }

  /**
   * Test SDK connectivity
   */
  public async testConnection(): Promise<boolean> {
    try {
      // Try to make a simple request to test connectivity
      const testUrl = `${this.config.apiBaseUrl}/v2.0/oa/getoa`;
      await this.client.apiGet(testUrl, "test-token");
      return true;
    } catch (error) {
      // We expect this to fail with authentication error, not network error
      if (
        (error as Error).message.includes("access_token") ||
        (error as Error).message.includes("401")
      ) {
        return true; // Network is working, just auth failed as expected
      }
      this.logger.error(`Connection test failed: ${(error as Error).message}`);
      return false;
    }
  }



  /**
   * Make a custom API request (advanced usage)
   */
  public async customRequest<T = any>(
    method: "GET" | "POST" | "PUT" | "DELETE",
    endpoint: string,
    accessToken: string,
    data?: any,
    params?: Record<string, any>
  ): Promise<T> {
    switch (method) {
      case "GET":
        return this.client.apiGet<T>(endpoint, accessToken, params);
      case "POST":
        return this.client.apiPost<T>(endpoint, accessToken, data, params);
      case "PUT":
        return this.client.apiPut<T>(endpoint, accessToken, data, params);
      case "DELETE":
        return this.client.apiDelete<T>(endpoint, accessToken, params);
      default:
        throw new ZaloSDKError(`Unsupported HTTP method: ${method}`);
    }
  }

  /**
   * Upload file to Zalo API
   */
  public async uploadFile<T = any>(
    endpoint: string,
    accessToken: string,
    file: Buffer | NodeJS.ReadableStream,
    filename: string,
    additionalFields?: Record<string, any>
  ): Promise<T> {
    return this.client.apiUploadFile<T>(
      endpoint,
      accessToken,
      file,
      filename,
      additionalFields
    );
  }

  /**
   * Dispose SDK resources
   */
  public dispose(): void {
    this.logger.info("Zalo SDK disposed");
  }
}
