/**
 * Main Zalo API client
 */

import { BaseClient } from "./base-client";
import { ZaloSDKConfig } from "../types/common";

/**
 * Zalo API client for making HTTP requests
 */
export class ZaloClient extends BaseClient {
  constructor(config: ZaloSDKConfig) {
    super(config);
  }

  /**
   * Make authenticated GET request to Zalo API
   */
  public async apiGet<T = any>(
    endpoint: string,
    accessToken: string,
    params?: Record<string, any>
  ): Promise<T> {
    return this.get<T>(endpoint, accessToken, params);
  }

  /**
   * Make GET request with custom headers
   */
  public async apiGetWithHeaders<T = any>(
    endpoint: string,
    headers: Record<string, string>
  ): Promise<T> {
    return this.request<T>({
      method: "GET",
      url: endpoint,
      headers,
    });
  }

  /**
   * Make authenticated POST request to Zalo API
   */
  public async apiPost<T = any>(
    endpoint: string,
    accessToken: string,
    data?: any,
    params?: Record<string, any>
  ): Promise<T> {
    return this.post<T>(endpoint, accessToken, data, params);
  }

  /**
   * Make authenticated POST request to Zalo API with custom headers
   */
  public async apiPostWithHeaders<T = any>(
    endpoint: string,
    accessToken: string,
    data?: any,
    customHeaders?: Record<string, string>
  ): Promise<T> {
    return this.request<T>({
      method: "POST",
      url: endpoint,
      headers: {
        access_token: accessToken,
        ...customHeaders,
      },
      data,
    });
  }

  /**
   * Make authenticated PUT request to Zalo API
   */
  public async apiPut<T = any>(
    endpoint: string,
    accessToken: string,
    data?: any,
    params?: Record<string, any>
  ): Promise<T> {
    return this.put<T>(endpoint, accessToken, data, params);
  }

  /**
   * Make authenticated DELETE request to Zalo API
   */
  public async apiDelete<T = any>(
    endpoint: string,
    accessToken: string,
    params?: Record<string, any>
  ): Promise<T> {
    return this.delete<T>(endpoint, accessToken, params);
  }

  /**
   * Upload file to Zalo API
   */
  public async apiUploadFile<T = any>(
    endpoint: string,
    accessToken: string,
    file: Buffer | NodeJS.ReadableStream,
    filename: string,
    additionalFields?: Record<string, any>
  ): Promise<T> {
    return this.uploadFile<T>(
      endpoint,
      accessToken,
      file,
      filename,
      additionalFields
    );
  }

  /**
   * Make POST request with FormData (for file uploads)
   */
  public async apiPostFormData<T = any>(
    endpoint: string,
    accessToken: string,
    formData: FormData
  ): Promise<T> {
    return this.request<T>({
      method: "POST",
      url: endpoint,
      headers: {
        access_token: accessToken,
        // Don't set Content-Type header, let the browser set it with boundary
      },
      data: formData,
    });
  }

  /**
   * Make request to OAuth endpoints (without access token)
   */
  public async oauthRequest<T = any>(
    method: "GET" | "POST",
    endpoint: string,
    data?: any,
    headers?: Record<string, string>
  ): Promise<T> {
    const config = {
      method,
      url: endpoint,
      headers,
      data,
    };

    if (method === "GET") {
      config.data = undefined;
      return this.get<T>(endpoint, undefined, data);
    } else {
      return this.post<T>(endpoint, undefined, data);
    }
  }

  /**
   * Make request to ZNS API (different base URL)
   */
  public async znsRequest<T = any>(
    method: "GET" | "POST" | "PUT" | "DELETE",
    endpoint: string,
    accessToken: string,
    data?: any,
    params?: Record<string, any>
  ): Promise<T> {
    const znsBaseUrl = "https://business.openapi.zalo.me";
    const fullUrl = `${znsBaseUrl}${endpoint}`;

    switch (method) {
      case "GET":
        return this.get<T>(fullUrl, accessToken, params);
      case "POST":
        return this.post<T>(fullUrl, accessToken, data, params);
      case "PUT":
        return this.put<T>(fullUrl, accessToken, data, params);
      case "DELETE":
        return this.delete<T>(fullUrl, accessToken, params);
      default:
        throw new Error(`Unsupported HTTP method: ${method}`);
    }
  }

  /**
   * Make request to OAuth endpoints with custom base URL
   */
  public async oauthRequestWithUrl<T = any>(
    method: "GET" | "POST",
    url: string,
    data?: any,
    headers?: Record<string, string>
  ): Promise<T> {
    return this.request<T>({
      method,
      url,
      headers: headers || {},
      data: method === "POST" ? data : undefined,
      params: method === "GET" ? data : undefined,
    });
  }
}
