/**
 * Template Type và Tag compatibility matrix
 */
export const ZNS_TEMPLATE_TAG_COMPATIBILITY: Record<ZNSTemplateType, ZNSTemplateTag[]> = {
  [ZNSTemplateType.CUSTOM]: [
    ZNSTemplateTag.TRANSACTION,
    ZNSTemplateTag.CUSTOMER_CARE,
    ZNSTemplateTag.PROMOTION
  ],
  [ZNSTemplateType.AUTHENTICATION]: [
    ZNSTemplateTag.TRANSACTION
  ],
  [ZNSTemplateType.PAYMENT_REQUEST]: [
    ZNSTemplateTag.TRANSACTION
  ],
  [ZNSTemplateType.VOUCHER]: [
    ZNSTemplateTag.TRANSACTION,
    ZNSTemplateTag.CUSTOMER_CARE,
    ZNSTemplateTag.PROMOTION
  ],
  [ZNSTemplateType.SERVICE_RATING]: [
    ZNSTemplateTag.CUSTOMER_CARE
  ]
};

/**
 * Validation functions
 */
export const ZNSValidation = {
  /**
   * Kiểm tra template name hợp lệ
   */
  isValidTemplateName: (name: string): boolean => {
    return name.length >= 10 && name.length <= 60;
  },

  /**
   * Kiểm tra note hợp lệ
   */
  isValidNote: (note: string): boolean => {
    return note.length >= 1 && note.length <= 400;
  },

  /**
   * Kiểm tra tag có tương thích với template type không
   */
  isTagCompatibleWithType: (templateType: ZNSTemplateType, tag: ZNSTemplateTag): boolean => {
    const compatibleTags = ZNS_TEMPLATE_TAG_COMPATIBILITY[templateType];
    return compatibleTags ? compatibleTags.includes(tag) : false;
  },

  /**
   * Kiểm tra param value có hợp lệ với type không
   */
  isValidParamValue: (paramType: ZNSParamType, value: string): boolean => {
    const typeInfo = ZNS_PARAM_TYPES[paramType];
    return typeInfo ? value.length <= typeInfo.maxLength : false;
  }
} as const;
