import { ZaloClient } from "../clients/zalo-client";
import { ZaloResponse, ZaloSDKError } from "../types/common";
import {
  AnonymousMessageRecipient,
  AnonymousMessageResponse,
} from "../types/message";

/**
 * Attachment cho gửi ảnh ẩn danh
 */
export interface AnonymousImageAttachment {
  type: "template";
  payload: {
    template_type: "media";
    elements: Array<{
      media_type: "image";
      url?: string;
      attachment_id?: string;
    }>;
  };
}

/**
 * Attachment cho gửi file ẩn danh
 */
export interface AnonymousFileAttachment {
  type: "file";
  payload: {
    token: string;
  };
}

/**
 * Attachment cho gửi sticker ẩn danh
 */
export interface AnonymousStickerAttachment {
  type: "template";
  payload: {
    template_type: "media";
    elements: Array<{
      media_type: "sticker";
      attachment_id: string;
    }>;
  };
}

/**
 * Request gửi tin nhắn văn bản đến người dùng ẩn danh
 */
export interface AnonymousTextMessageRequest {
  recipient: AnonymousMessageRecipient;
  message: {
    text: string;
  };
}

/**
 * Request gửi tin nhắn ảnh đến người dùng ẩn danh
 */
export interface AnonymousImageMessageRequest {
  recipient: AnonymousMessageRecipient;
  message: {
    attachment: AnonymousImageAttachment;
  };
}

/**
 * Request gửi tin nhắn file đến người dùng ẩn danh
 */
export interface AnonymousFileMessageRequest {
  recipient: AnonymousMessageRecipient;
  message: {
    attachment: AnonymousFileAttachment;
  };
}

/**
 * Request gửi tin nhắn sticker đến người dùng ẩn danh
 */
export interface AnonymousStickerMessageRequest {
  recipient: AnonymousMessageRecipient;
  message: {
    attachment: AnonymousStickerAttachment;
  };
}

/**
 * Service xử lý các API gửi tin nhắn đến người dùng ẩn danh của Zalo Official Account
 *
 * Bao gồm các chức năng:
 * - Gửi tin nhắn văn bản đến người dùng ẩn danh
 * - Gửi tin nhắn ảnh đến người dùng ẩn danh
 * - Gửi tin nhắn file đến người dùng ẩn danh
 * - Gửi tin nhắn sticker đến người dùng ẩn danh
 *
 * ĐIỀU KIỆN SỬ DỤNG:
 *
 * 1. QUYỀN TRUY CẬP:
 *    - Cần quyền: Gửi tin và thông báo qua OA
 *
 * 2. THÔNG TIN NGƯỜI DÙNG ẨN DANH:
 *    - anonymous_id: ID đại diện cho người dùng ẩn danh
 *    - conversation_id: ID của cuộc hội thoại
 *    - Các thông tin này nhận được từ webhook khi người dùng ẩn danh gửi tin nhắn
 *
 * 3. GIỚI HẠN:
 *    - Tin nhắn văn bản: Tối đa 2000 ký tự
 *    - Tin nhắn ảnh: Hỗ trợ định dạng JPG, PNG, dung lượng tối đa 1MB
 *    - Tin nhắn sticker: Sử dụng sticker_id từ nguồn https://stickers.zaloapp.com/
 *    - Tin nhắn file: Sử dụng token từ API upload file
 */
export class AnonymousMessageService {
  private readonly endpoint = "https://openapi.zalo.me/v2.0/oa/message";

  constructor(private readonly client: ZaloClient) {}

  /**
   * Gửi tin nhắn văn bản đến người dùng ẩn danh
   *
   * @param accessToken Access token của Official Account
   * @param recipient Thông tin người nhận ẩn danh
   * @param text Nội dung văn bản (tối đa 2000 ký tự)
   * @returns Thông tin tin nhắn đã gửi
   *
   * @example
   * ```typescript
   * const result = await anonymousService.sendTextMessage(
   *   accessToken,
   *   { anonymous_id: 'xxx', conversation_id: 'yyy' },
   *   'hello, world!'
   * );
   * ```
   */
  async sendTextMessage(
    accessToken: string,
    recipient: AnonymousMessageRecipient,
    text: string
  ): Promise<AnonymousMessageResponse> {
    try {
      // Validate text length theo docs: tối đa 2000 ký tự
      if (text.length > 2000) {
        throw new ZaloSDKError(
          "Nội dung văn bản không được vượt quá 2000 ký tự",
          -1
        );
      }

      if (text.trim().length === 0) {
        throw new ZaloSDKError("Nội dung văn bản không được để trống", -1);
      }

      const request: AnonymousTextMessageRequest = {
        recipient,
        message: { text },
      };

      const result: ZaloResponse<AnonymousMessageResponse> =
        await this.client.apiPost(this.endpoint, accessToken, request);

      if (result.error !== 0) {
        throw new ZaloSDKError(
          result.message || "Failed to send anonymous text message",
          result.error,
          result
        );
      }

      if (!result.data) {
        throw new ZaloSDKError("No response data received", -1);
      }

      return result.data;
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(
        `Failed to send anonymous text message: ${(error as Error).message}`,
        -1,
        error
      );
    }
  }

  /**
   * Gửi tin nhắn ảnh đến người dùng ẩn danh
   *
   * @param accessToken Access token của Official Account
   * @param recipient Thông tin người nhận ẩn danh
   * @param imageUrl URL của ảnh (định dạng JPG/PNG, tối đa 1MB) HOẶC attachment_id từ upload
   * @returns Thông tin tin nhắn đã gửi
   *
   * @example
   * ```typescript
   * // Gửi bằng URL
   * const result = await anonymousService.sendImageMessage(
   *   accessToken,
   *   { anonymous_id: 'xxx', conversation_id: 'yyy' },
   *   'https://example.com/image.jpg'
   * );
   *
   * // Gửi bằng attachment_id
   * const result2 = await anonymousService.sendImageMessage(
   *   accessToken,
   *   { anonymous_id: 'xxx', conversation_id: 'yyy' },
   *   undefined,
   *   'uploaded_attachment_id'
   * );
   * ```
   */
  async sendImageMessage(
    accessToken: string,
    recipient: AnonymousMessageRecipient,
    imageUrl?: string,
    attachmentId?: string
  ): Promise<AnonymousMessageResponse> {
    try {
      if (!imageUrl && !attachmentId) {
        throw new ZaloSDKError(
          "Phải cung cấp imageUrl hoặc attachmentId",
          -1
        );
      }

      const attachment: AnonymousImageAttachment = {
        type: "template",
        payload: {
          template_type: "media",
          elements: [
            {
              media_type: "image",
              ...(imageUrl && { url: imageUrl }),
              ...(attachmentId && { attachment_id: attachmentId }),
            },
          ],
        },
      };

      const request: AnonymousImageMessageRequest = {
        recipient,
        message: { attachment },
      };

      const result: ZaloResponse<AnonymousMessageResponse> =
        await this.client.apiPost(this.endpoint, accessToken, request);

      if (result.error !== 0) {
        throw new ZaloSDKError(
          result.message || "Failed to send anonymous image message",
          result.error,
          result
        );
      }

      if (!result.data) {
        throw new ZaloSDKError("No response data received", -1);
      }

      return result.data;
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(
        `Failed to send anonymous image message: ${(error as Error).message}`,
        -1,
        error
      );
    }
  }

  /**
   * Gửi tin nhắn file đến người dùng ẩn danh
   *
   * @param accessToken Access token của Official Account
   * @param recipient Thông tin người nhận ẩn danh
   * @param fileToken Token từ API upload file
   * @returns Thông tin tin nhắn đã gửi
   *
   * @example
   * ```typescript
   * // Đầu tiên upload file
   * const uploadResult = await messageService.uploadFile(accessToken, fileData, fileName);
   *
   * // Sau đó gửi tin nhắn file
   * const result = await anonymousService.sendFileMessage(
   *   accessToken,
   *   { anonymous_id: 'xxx', conversation_id: 'yyy' },
   *   uploadResult.token
   * );
   * ```
   */
  async sendFileMessage(
    accessToken: string,
    recipient: AnonymousMessageRecipient,
    fileToken: string
  ): Promise<AnonymousMessageResponse> {
    try {
      if (!fileToken || fileToken.trim().length === 0) {
        throw new ZaloSDKError("File token không được để trống", -1);
      }

      const attachment: AnonymousFileAttachment = {
        type: "file",
        payload: {
          token: fileToken,
        },
      };

      const request: AnonymousFileMessageRequest = {
        recipient,
        message: { attachment },
      };

      const result: ZaloResponse<AnonymousMessageResponse> =
        await this.client.apiPost(this.endpoint, accessToken, request);

      if (result.error !== 0) {
        throw new ZaloSDKError(
          result.message || "Failed to send anonymous file message",
          result.error,
          result
        );
      }

      if (!result.data) {
        throw new ZaloSDKError("No response data received", -1);
      }

      return result.data;
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(
        `Failed to send anonymous file message: ${(error as Error).message}`,
        -1,
        error
      );
    }
  }

  /**
   * Gửi tin nhắn sticker đến người dùng ẩn danh
   *
   * @param accessToken Access token của Official Account
   * @param recipient Thông tin người nhận ẩn danh
   * @param stickerId ID của sticker (lấy từ https://stickers.zaloapp.com/)
   * @returns Thông tin tin nhắn đã gửi
   *
   * @example
   * ```typescript
   * const result = await anonymousService.sendStickerMessage(
   *   accessToken,
   *   { anonymous_id: 'xxx', conversation_id: 'yyy' },
   *   'sticker_id_from_zalo'
   * );
   * ```
   */
  async sendStickerMessage(
    accessToken: string,
    recipient: AnonymousMessageRecipient,
    stickerId: string
  ): Promise<AnonymousMessageResponse> {
    try {
      if (!stickerId || stickerId.trim().length === 0) {
        throw new ZaloSDKError("Sticker ID không được để trống", -1);
      }

      const attachment: AnonymousStickerAttachment = {
        type: "template",
        payload: {
          template_type: "media",
          elements: [
            {
              media_type: "sticker",
              attachment_id: stickerId,
            },
          ],
        },
      };

      const request: AnonymousStickerMessageRequest = {
        recipient,
        message: { attachment },
      };

      const result: ZaloResponse<AnonymousMessageResponse> =
        await this.client.apiPost(this.endpoint, accessToken, request);

      if (result.error !== 0) {
        throw new ZaloSDKError(
          result.message || "Failed to send anonymous sticker message",
          result.error,
          result
        );
      }

      if (!result.data) {
        throw new ZaloSDKError("No response data received", -1);
      }

      return result.data;
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(
        `Failed to send anonymous sticker message: ${(error as Error).message}`,
        -1,
        error
      );
    }
  }
}
