import { ZaloClient } from "../clients/zalo-client";
import { ZaloResponse, ZaloSDKError } from "../types/common";

/**
 * Interface cho thông tin quota tin nhắn
 */
export interface MessageQuotaInfo {
  quota: number;
  used: number;
  remaining: number;
  reset_time: number;
}

/**
 * Interface cho tin nhắn trong cuộc hội thoại - matches Zalo API docs exactly
 */
export interface ConversationMessage {
  /** ID của tin nhắn */
  message_id: string;
  /** Thuộc tính cho biết tin nhắn được gửi từ OA hoặc người dùng. 0: tin nhắn từ OA đến user, 1: tin nhắn từ user đến OA */
  src: number;
  /** Thời gian tin nhắn được gửi (định dạng timestamp) */
  time: number;
  /** Loại tin nhắn: text, voice, photo, GIF, link, links, sticker, location */
  type: string;
  /** Nội dung tin nhắn */
  message: string;
  /** Thuộc tính trả về 1 danh sách các đường dẫn được đính kèm trong tin nhắn (chỉ có khi type là link hoặc links) */
  links?: string[];
  /** URL của ảnh hoặc GIF (chỉ có khi type là GIF hoặc photo) */
  thumb?: string;
  /** Đường dẫn đến audio/ảnh/GIF/nhãn dán */
  url?: string;
  /** Mô tả của ảnh (chỉ có khi type là photo) */
  description?: string;
  /** ID của đối tượng gửi tin nhắn (có thể là user_id hoặc oa_id) */
  from_id: string;
  /** ID của đối tượng nhận tin nhắn (có thể là user_id hoặc oa_id) */
  to_id: string;
  /** Tên hiển thị của đối tượng gửi tin nhắn */
  from_display_name: string;
  /** Đường dẫn đến ảnh đại diện của đối tượng gửi tin nhắn */
  from_avatar: string;
  /** Tên hiển thị của đối tượng nhận tin nhắn */
  to_display_name: string;
  /** Đường dẫn đến ảnh đại diện của đối tượng nhận tin nhắn */
  to_avatar: string;
  /** Thuộc tính trả về giá trị longitude và latitude của người dùng (chỉ có khi type là location) */
  location?: string;
}

/**
 * Interface cho cuộc hội thoại
 */
export interface Conversation {
  conversation_id: string;
  user_id: string;
  last_message: ConversationMessage;
  unread_count: number;
  updated_time: number;
}

/**
 * Interface cho kết quả upload file - matches Zalo API docs exactly
 */
export interface UploadFileResult {
  /** Token của file, sử dụng cho API gửi thông báo đính kèm file */
  token: string;
}

/**
 * Interface cho kết quả upload image - matches Zalo API docs exactly
 */
export interface UploadImageResult {
  /** ID của ảnh được upload */
  attachment_id: string;
}


/**
 * Service xử lý các API quản lý tin nhắn của Zalo Official Account
 *
 * Bao gồm các chức năng:
 * - Kiểm tra hạn mức gửi tin nhắn
 * - Lấy danh sách tin nhắn trong cuộc hội thoại với user cụ thể
 * - Lấy thông tin tin nhắn gần nhất
 * - Upload file và hình ảnh
 *
 * ĐIỀU KIỆN SỮCDNG:
 *
 * 1. KIỂM TRA HẠN MỨC:
 *    - Cần quyền truy cập thông tin quota từ Zalo
 *    - Quota được reset hàng ngày vào 00:00 GMT+7
 *
 * 2. LẤY TIN NHẮN:
 *    - API hỗ trợ lấy thông tin tin nhắn giữa OA và một người dùng cụ thể
 *    - Mỗi request lấy tối đa được 10 tin nhắn
 *    - Tin nhắn gần nhất có thứ tự là 0
 *
 * 3. UPLOAD FILE:
 *    - Kích thước tối đa 5MB
 *    - Hỗ trợ các định dạng: PDF, DOC, DOCX
 *    - Quota: 5000 request/tháng
 *
 * 4. UPLOAD HÌNH ẢNH:
 *    - Dung lượng tối đa 1MB
 *    - Hỗ trợ các định dạng: JPG và PNG
 *    - Ảnh sẽ được lưu trên server tối đa 7 ngày
 *    - Quota: 5000 request/tháng
 *
 * 5. UPLOAD ẢNH GIF:
 *    - Kích thước tối đa 5MB
 *    - Chỉ hỗ trợ định dạng GIF
 *    - Ảnh GIF được lưu trên server tối đa 7 ngày
 *    - Quota: 5000 request/tháng
 */
export class MessageManagementService {
  // Zalo API endpoints - organized by functionality
  private readonly endpoints = {
    // Message management endpoints
    message: {
      quota: "https://openapi.zalo.me/v2.0/oa/quota",
      conversation: "https://openapi.zalo.me/v2.0/oa/conversation",
      recentConversations: "https://openapi.zalo.me/v2.0/oa/listrecentchat",
    },
    // Upload endpoints
    upload: {
      file: "https://openapi.zalo.me/v2.0/oa/upload/file",
      image: "https://openapi.zalo.me/v2.0/oa/upload/image",
      gif: "https://openapi.zalo.me/v2.0/oa/upload/gif",
    },
  };

  constructor(private readonly client: ZaloClient) {}

  /**
   * Kiểm tra hạn mức gửi tin nhắn đến user cụ thể
   * @param accessToken Access token của Official Account
   * @param userId ID của người dùng Zalo
   * @returns Thông tin hạn mức gửi tin nhắn
   */
  async checkMessageQuota(
    accessToken: string,
    userId: string
  ): Promise<MessageQuotaInfo> {
    try {
      const result: ZaloResponse<MessageQuotaInfo> = await this.client.apiGet(
        this.endpoints.message.quota,
        accessToken,
        { user_id: userId }
      );

      if (result.error !== 0) {
        throw new ZaloSDKError(
          result.message || "Failed to check message quota",
          result.error,
          result
        );
      }

      if (!result.data) {
        throw new ZaloSDKError("No quota data received", -1);
      }

      return result.data;
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(
        `Failed to check message quota: ${(error as Error).message}`,
        -1,
        error
      );
    }
  }

  /**
   * Lấy danh sách tin nhắn trong cuộc hội thoại với user
   *
   * API hỗ trợ lấy thông tin tin nhắn giữa OA và một người dùng cụ thể.
   *
   * @param accessToken Access token của Official Account
   * @param userId ID của người dùng Zalo cần lấy danh sách hội thoại
   * @param offset Thứ tự của tin nhắn đầu tiên trong danh sách trả về (tin nhắn gần nhất có thứ tự là 0)
   * @param count Số lượng tin nhắn cần lấy (mỗi request lấy tối đa 10 tin nhắn)
   * @returns Danh sách tin nhắn
   *
   * @example
   * ```typescript
   * const messages = await messageService.getConversationMessages(
   *   accessToken,
   *   '2512523625412515',
   *   0,
   *   5
   * );
   * ```
   */
  async getConversationMessages(
    accessToken: string,
    userId: string,
    offset: number = 0,
    count: number = 10
  ): Promise<ConversationMessage[]> {
    try {
      // Validate count theo docs: mỗi request lấy tối đa 10 tin nhắn
      if (count > 10) {
        throw new ZaloSDKError("Mỗi request lấy tối đa được 10 tin nhắn", -1);
      }

      // Theo docs Zalo: params phải được wrap trong object data dạng JSON string
      const params = {
        data: JSON.stringify({
          user_id: userId,
          offset,
          count,
        }),
      };

      const result: ZaloResponse<ConversationMessage[]> = await this.client.apiGet(
        this.endpoints.message.conversation,
        accessToken,
        params
      );

      if (result.error !== 0) {
        throw new ZaloSDKError(
          result.message || "Failed to get conversation messages",
          result.error,
          result
        );
      }

      if (!result.data) {
        throw new ZaloSDKError("No conversation data received", -1);
      }

      // Response trả về mảng trực tiếp trong data
      return result.data;
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(
        `Failed to get conversation messages: ${(error as Error).message}`,
        -1,
        error
      );
    }
  }

  /**
   * Lấy danh sách tin nhắn trong cuộc hội thoại với user (sử dụng POST method)
   *
   * API hỗ trợ lấy thông tin tin nhắn giữa OA và một người dùng cụ thể sử dụng phương thức POST.
   *
   * @param accessToken Access token của Official Account
   * @param userId ID của người dùng Zalo cần lấy danh sách hội thoại
   * @param offset Thứ tự của tin nhắn đầu tiên trong danh sách trả về (tin nhắn gần nhất có thứ tự là 0)
   * @param count Số lượng tin nhắn cần lấy (mỗi request lấy tối đa 10 tin nhắn)
   * @returns Danh sách tin nhắn
   *
   * @example
   * ```typescript
   * const messages = await messageService.postConversationMessages(
   *   accessToken,
   *   '2512523625412515',
   *   0,
   *   5
   * );
   * ```
   */
  async postConversationMessages(
    accessToken: string,
    userId: string,
    offset: number = 0,
    count: number = 10
  ): Promise<ConversationMessage[]> {
    try {
      // Validate count theo docs: mỗi request lấy tối đa 10 tin nhắn
      if (count > 10) {
        throw new ZaloSDKError("Mỗi request lấy tối đa được 10 tin nhắn", -1);
      }

      // Body format for POST request - gửi trực tiếp các tham số
      const body = {
        user_id: userId,
        offset,
        count,
      };

      const result: ZaloResponse<ConversationMessage[]> = await this.client.apiPost(
        this.endpoints.message.conversation,
        accessToken,
        body
      );

      if (result.error !== 0) {
        throw new ZaloSDKError(
          result.message || "Failed to get conversation messages",
          result.error,
          result
        );
      }

      if (!result.data) {
        throw new ZaloSDKError("No conversation data received", -1);
      }

      // Response trả về mảng trực tiếp trong data
      return result.data;
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(
        `Failed to get conversation messages: ${(error as Error).message}`,
        -1,
        error
      );
    }
  }

  /**
   * Lấy thông tin tin nhắn gần nhất
   * 
   * API hỗ trợ lấy thông tin tối đa 10 tin nhắn gần nhất giữa OA và người dùng.
   * 
   * @param accessToken Access token của Official Account
   * @param offset Thứ tự của tin nhắn đầu tiên trong danh sách trả về (tin nhắn gần nhất có thứ tự là 0)
   * @param count Số lượng tin nhắn muốn lấy (mỗi request lấy tối đa 10 tin nhắn)
   * @returns Danh sách tin nhắn gần nhất
   * 
   * @example
   * ```typescript
   * const recentMessages = await messageService.getRecentConversations(
   *   accessToken,
   *   0,
   *   5
   * );
   * ```
   */
  async getRecentConversations(
    accessToken: string,
    offset: number = 0,
    count: number = 10
  ): Promise<ConversationMessage[]> {
    try {
      // Validate count theo docs: mỗi request lấy tối đa 10 tin nhắn
      if (count > 10) {
        throw new ZaloSDKError("Mỗi request lấy tối đa 10 tin nhắn", -1);
      }

      // Theo docs Zalo: params phải được wrap trong object data dạng JSON string
      const params = {
        data: JSON.stringify({
          offset,
          count,
        }),
      };

      const result: ZaloResponse<ConversationMessage[]> = await this.client.apiGet(
        this.endpoints.message.recentConversations,
        accessToken,
        params
      );

      if (result.error !== 0) {
        throw new ZaloSDKError(
          result.message || "Failed to get recent messages",
          result.error,
          result
        );
      }

      if (!result.data) {
        throw new ZaloSDKError("No recent messages data received", -1);
      }

      // Response trả về mảng trực tiếp trong data
      return result.data;
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(
        `Failed to get recent messages: ${(error as Error).message}`,
        -1,
        error
      );
    }
  }

  /**
   * Upload file để sử dụng trong tin nhắn
   * @param accessToken Access token của Official Account
   * @param fileData Dữ liệu file (base64 hoặc buffer)
   * @param fileName Tên file
   * @returns Token của file đã upload
   *
   * Lưu ý:
   * - Chỉ hỗ trợ file PDF/DOC/DOCX
   * - Dung lượng file không vượt quá 5MB
   * - File sẽ được lưu trên server tối đa 7 ngày
   * - Quota: 5000 request/tháng
   */
  async uploadFile(
    accessToken: string,
    fileData: string | Buffer,
    fileName: string
  ): Promise<UploadFileResult> {
    try {
      // Validate file format (only PDF/DOC/DOCX)
      const allowedExtensions = ['.pdf', '.doc', '.docx'];
      const fileExt = fileName.toLowerCase().substring(fileName.lastIndexOf('.'));
      if (!allowedExtensions.includes(fileExt)) {
        throw new ZaloSDKError("Chỉ hỗ trợ file PDF, DOC, DOCX", -1);
      }

      // Validate file size (max 5MB)
      const maxSize = 5 * 1024 * 1024; // 5MB
      let fileSize: number;

      if (typeof fileData === "string") {
        // Base64 string
        fileSize = Buffer.from(fileData, "base64").length;
      } else {
        // Buffer
        fileSize = fileData.length;
      }

      if (fileSize > maxSize) {
        throw new ZaloSDKError("Kích thước file không được vượt quá 5MB", -1);
      }

      let buffer: Buffer;
      if (typeof fileData === "string") {
        buffer = Buffer.from(fileData, "base64");
      } else {
        buffer = fileData;
      }

      const result: ZaloResponse<UploadFileResult> = await this.client.apiUploadFile(
        this.endpoints.upload.file,
        accessToken,
        buffer,
        fileName
      );

      if (result.error !== 0) {
        throw new ZaloSDKError(
          result.message || "Failed to upload file",
          result.error,
          result
        );
      }

      if (!result.data) {
        throw new ZaloSDKError("No upload result received", -1);
      }

      return result.data;
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(
        `Failed to upload file: ${(error as Error).message}`,
        -1,
        error
      );
    }
  }

  /**
   * Upload hình ảnh để sử dụng trong tin nhắn
   * @param accessToken Access token của Official Account
   * @param imageData Dữ liệu hình ảnh (base64 hoặc buffer)
   * @param fileName Tên file hình ảnh
   * @returns ID của ảnh đã upload
   *
   * Lưu ý:
   * - Hỗ trợ các định dạng: JPG và PNG
   * - Dung lượng tối đa: 1MB
   * - Ảnh sẽ được lưu trên server tối đa 7 ngày
   * - Quota: 5000 request/tháng
   */
  async uploadImage(
    accessToken: string,
    imageData: string | Buffer,
    fileName: string
  ): Promise<UploadImageResult> {
    try {
      // Validate image size (max 1MB)
      const maxSize = 1 * 1024 * 1024; // 1MB
      let imageSize: number;

      if (typeof imageData === "string") {
        // Base64 string
        imageSize = Buffer.from(imageData, "base64").length;
      } else {
        // Buffer
        imageSize = imageData.length;
      }

      if (imageSize > maxSize) {
        throw new ZaloSDKError(
          "Kích thước hình ảnh không được vượt quá 1MB",
          -1
        );
      }

      let buffer: Buffer;
      if (typeof imageData === "string") {
        buffer = Buffer.from(imageData, "base64");
      } else {
        buffer = imageData;
      }

      const result: ZaloResponse<UploadImageResult> = await this.client.apiUploadFile(
        this.endpoints.upload.image,
        accessToken,
        buffer,
        fileName
      );

      if (result.error !== 0) {
        throw new ZaloSDKError(
          result.message || "Failed to upload image",
          result.error,
          result
        );
      }

      if (!result.data) {
        throw new ZaloSDKError("No upload result received", -1);
      }

      return result.data;
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(
        `Failed to upload image: ${(error as Error).message}`,
        -1,
        error
      );
    }
  }

  /**
   * Upload ảnh GIF để sử dụng trong tin nhắn
   * @param accessToken Access token của Official Account
   * @param gifData Dữ liệu ảnh GIF (base64 hoặc buffer)
   * @param fileName Tên file ảnh GIF
   * @returns Thông tin ảnh GIF đã upload
   *
   * Lưu ý:
   * - Dung lượng tối đa: 5MB
   * - Ảnh GIF sẽ được lưu trên server tối đa 7 ngày
   * - Quota: 5000 request/tháng
   * - Định dạng hỗ trợ: GIF
   */
  async uploadGif(
    accessToken: string,
    gifData: string | Buffer,
    fileName: string
  ): Promise<UploadImageResult> {
    try {
      // Validate GIF size (max 5MB)
      const maxSize = 5 * 1024 * 1024; // 5MB
      let gifSize: number;

      if (typeof gifData === "string") {
        // Base64 string
        gifSize = Buffer.from(gifData, "base64").length;
      } else {
        // Buffer
        gifSize = gifData.length;
      }

      if (gifSize > maxSize) {
        throw new ZaloSDKError(
          "Kích thước ảnh GIF không được vượt quá 5MB",
          -1
        );
      }

      // Validate file extension
      if (!fileName.toLowerCase().endsWith(".gif")) {
        throw new ZaloSDKError("File phải có định dạng GIF", -1);
      }

      let buffer: Buffer;
      if (typeof gifData === "string") {
        buffer = Buffer.from(gifData, "base64");
      } else {
        buffer = gifData;
      }

      const result: ZaloResponse<UploadImageResult> = await this.client.apiUploadFile(
        this.endpoints.upload.gif,
        accessToken,
        buffer,
        fileName
      );

      if (result.error !== 0) {
        throw new ZaloSDKError(
          result.message || "Failed to upload GIF",
          result.error,
          result
        );
      }

      if (!result.data) {
        throw new ZaloSDKError("No upload result received", -1);
      }

      return result.data;
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(
        `Failed to upload GIF: ${(error as Error).message}`,
        -1,
        error
      );
    }
  }
}
