import { ZaloClient } from "../clients/zalo-client";
import { ZaloResponse, ZaloSDKError } from "../types/common";
import {
  MessageRecipient,
  SenderAction,
  MessageReactionResponse,
  ReactIcon,
} from "../types/message";

/**
 * Request thả biểu tượng cảm xúc vào tin nhắn
 */
export interface MessageReactionRequest {
  recipient: MessageRecipient;
  sender_action: SenderAction;
}

/**
 * Service xử lý API thả biểu tượng cảm xúc vào tin nhắn của Zalo Official Account
 *
 * Bao gồm chức năng:
 * - Thả biểu tượng cảm xúc vào tin nhắn
 * - Thu hồi biểu tượng cảm xúc
 *
 * ĐIỀU KIỆN SỬ DỤNG:
 *
 * 1. QUYỀN TRUY CẬP:
 *    - Cần quyền: Gửi tin nhắn / Thả biểu tượng cảm xúc vào tin nhắn
 *
 * 2. GIỚI HẠN:
 *    - Một message_id chỉ được thả tối đa 50 biểu tượng cảm xúc
 *    - API này KHÔNG bị tính vào quota chủ động hàng tháng
 *
 * 3. CÁC BIỂU TƯỢNG CẢM XÚC HỖ TRỢ:
 *    - :> (Thích - Like)
 *    - --b (Haha)
 *    - :-(( (Buồn - Sad)
 *    - /-strong (Mạnh mẽ - Strong)
 *    - /-heart (Yêu thích - Love)
 *    - :-h (Ngạc nhiên - Wow)
 *    - :o (Wow)
 *    - /-remove (Thu hồi biểu tượng cảm xúc)
 */
export class MessageReactionService {
  private readonly endpoint = "https://openapi.zalo.me/v2.0/oa/message";

  constructor(private readonly client: ZaloClient) {}

  /**
   * Thả biểu tượng cảm xúc vào tin nhắn
   *
   * @param accessToken Access token của Official Account
   * @param userId ID của người nhận
   * @param messageId message_id của tin nhắn cần thả cảm xúc
   * @param reactIcon Biểu tượng cảm xúc
   * @returns Thông tin tin nhắn phản hồi
   *
   * @example
   * ```typescript
   * // Thả icon tim
   * const result = await reactionService.reactToMessage(
   *   accessToken,
   *   '186729651760683225',
   *   '789f573aecf8a9a4f0eb',
   *   '/-heart'
   * );
   *
   * // Thu hồi biểu tượng cảm xúc
   * const removeResult = await reactionService.reactToMessage(
   *   accessToken,
   *   '186729651760683225',
   *   '789f573aecf8a9a4f0eb',
   *   '/-remove'
   * );
   * ```
   */
  async reactToMessage(
    accessToken: string,
    userId: string,
    messageId: string,
    reactIcon: ReactIcon
  ): Promise<MessageReactionResponse> {
    try {
      // Validate inputs
      if (!userId || userId.trim().length === 0) {
        throw new ZaloSDKError("User ID không được để trống", -1);
      }

      if (!messageId || messageId.trim().length === 0) {
        throw new ZaloSDKError("Message ID không được để trống", -1);
      }

      // Danh sách các react icon hợp lệ
      const validIcons: ReactIcon[] = [
        ":>",
        "--b",
        ":-((",
        "/-strong",
        "/-heart",
        ":-h",
        ":o",
        "/-remove",
      ];

      if (!validIcons.includes(reactIcon)) {
        throw new ZaloSDKError(
          `Biểu tượng cảm xúc không hợp lệ. Các giá trị hợp lệ: ${validIcons.join(
            ", "
          )}`,
          -1
        );
      }

      const request: MessageReactionRequest = {
        recipient: {
          user_id: userId,
        },
        sender_action: {
          react_icon: reactIcon,
          react_message_id: messageId,
        },
      };

      const result: ZaloResponse<MessageReactionResponse> =
        await this.client.apiPost(this.endpoint, accessToken, request);

      if (result.error !== 0) {
        throw new ZaloSDKError(
          result.message || "Failed to react to message",
          result.error,
          result
        );
      }

      if (!result.data) {
        throw new ZaloSDKError("No response data received", -1);
      }

      return result.data;
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(
        `Failed to react to message: ${(error as Error).message}`,
        -1,
        error
      );
    }
  }

  /**
   * Thả icon "Thích" (Like) vào tin nhắn
   *
   * @param accessToken Access token của Official Account
   * @param userId ID của người nhận
   * @param messageId message_id của tin nhắn cần thả cảm xúc
   * @returns Thông tin tin nhắn phản hồi
   */
  async likeMessage(
    accessToken: string,
    userId: string,
    messageId: string
  ): Promise<MessageReactionResponse> {
    return this.reactToMessage(accessToken, userId, messageId, ":>");
  }

  /**
   * Thả icon "Haha" vào tin nhắn
   *
   * @param accessToken Access token của Official Account
   * @param userId ID của người nhận
   * @param messageId message_id của tin nhắn cần thả cảm xúc
   * @returns Thông tin tin nhắn phản hồi
   */
  async hahaMessage(
    accessToken: string,
    userId: string,
    messageId: string
  ): Promise<MessageReactionResponse> {
    return this.reactToMessage(accessToken, userId, messageId, "--b");
  }

  /**
   * Thả icon "Buồn" (Sad) vào tin nhắn
   *
   * @param accessToken Access token của Official Account
   * @param userId ID của người nhận
   * @param messageId message_id của tin nhắn cần thả cảm xúc
   * @returns Thông tin tin nhắn phản hồi
   */
  async sadMessage(
    accessToken: string,
    userId: string,
    messageId: string
  ): Promise<MessageReactionResponse> {
    return this.reactToMessage(accessToken, userId, messageId, ":-((");
  }

  /**
   * Thả icon "Mạnh mẽ" (Strong) vào tin nhắn
   *
   * @param accessToken Access token của Official Account
   * @param userId ID của người nhận
   * @param messageId message_id của tin nhắn cần thả cảm xúc
   * @returns Thông tin tin nhắn phản hồi
   */
  async strongMessage(
    accessToken: string,
    userId: string,
    messageId: string
  ): Promise<MessageReactionResponse> {
    return this.reactToMessage(accessToken, userId, messageId, "/-strong");
  }

  /**
   * Thả icon "Yêu thích" (Love) vào tin nhắn
   *
   * @param accessToken Access token của Official Account
   * @param userId ID của người nhận
   * @param messageId message_id của tin nhắn cần thả cảm xúc
   * @returns Thông tin tin nhắn phản hồi
   */
  async loveMessage(
    accessToken: string,
    userId: string,
    messageId: string
  ): Promise<MessageReactionResponse> {
    return this.reactToMessage(accessToken, userId, messageId, "/-heart");
  }

  /**
   * Thả icon "Ngạc nhiên" (Wow) vào tin nhắn
   *
   * @param accessToken Access token của Official Account
   * @param userId ID của người nhận
   * @param messageId message_id của tin nhắn cần thả cảm xúc
   * @returns Thông tin tin nhắn phản hồi
   */
  async wowMessage(
    accessToken: string,
    userId: string,
    messageId: string
  ): Promise<MessageReactionResponse> {
    return this.reactToMessage(accessToken, userId, messageId, ":-h");
  }

  /**
   * Thu hồi biểu tượng cảm xúc khỏi tin nhắn
   *
   * @param accessToken Access token của Official Account
   * @param userId ID của người nhận
   * @param messageId message_id của tin nhắn cần thu hồi cảm xúc
   * @returns Thông tin tin nhắn phản hồi
   */
  async removeReaction(
    accessToken: string,
    userId: string,
    messageId: string
  ): Promise<MessageReactionResponse> {
    return this.reactToMessage(accessToken, userId, messageId, "/-remove");
  }
}

/**
 * Enum các loại biểu tượng cảm xúc hỗ trợ
 */
export enum ReactionIcon {
  /** Thích (Like) */
  LIKE = ":>",
  /** Haha */
  HAHA = "--b",
  /** Buồn (Sad) */
  SAD = ":-((",
  /** Mạnh mẽ (Strong) */
  STRONG = "/-strong",
  /** Yêu thích (Love) */
  HEART = "/-heart",
  /** Ngạc nhiên (Wow) */
  WOW_H = ":-h",
  /** Wow */
  WOW_O = ":o",
  /** Thu hồi biểu tượng cảm xúc */
  REMOVE = "/-remove",
}
