  /**
   * Bulk tag operations
   */
  public async bulkAddTag(
    accessToken: string,
    userIds: string[],
    tagName: string
  ): Promise<{ success: string[]; failed: string[] }> {
    const results: { success: string[]; failed: string[] } = {
      success: [],
      failed: [],
    };

    for (const userId of userIds) {
      try {
        await this.addTagToUser(accessToken, {
          user_id: userId,
          tag_name: tagName,
        });
        results.success.push(userId);
      } catch (error) {
        results.failed.push(userId);
      }
    }

    return results;
  }

  /**
   * Bulk remove tag operations
   */
  public async bulkRemoveTag(
    accessToken: string,
    userIds: string[],
    tagName: string
  ): Promise<{ success: string[]; failed: string[] }> {
    const results: { success: string[]; failed: string[] } = {
      success: [],
      failed: [],
    };

    for (const userId of userIds) {
      try {
        await this.removeTagFromUser(accessToken, {
          user_id: userId,
          tag_name: tagName,
        });
        results.success.push(userId);
      } catch (error) {
        results.failed.push(userId);
      }
    }

    return results;
  }

  private handleError(error: unknown, message: string): never {
    const errorMessage =
      error instanceof Error ? error.message : "Unknown error";
    throw new ZaloSDKError(`${message}: ${errorMessage}`, -1, error);
  }
