/**
 * RedAI Zalo SDK - Main entry point
 *
 * A comprehensive TypeScript SDK for Zalo APIs including:
 * - Official Account (OA) API
 * - Zalo Notification Service (ZNS)
 * - Social API
 * - Group Message Framework (GMF)
 * - Webhook handling
 */

// Export types
export * from "./types/common";
export * from "./types/auth";
export * from "./types/oa";
export * from "./types/user";
export * from "./types/zns";
export * from "./types/article";
export * from "./types/broadcast";
export * from "./types/promotion";
export * from "./types/consultation";
export * from "./types/purchase";
export type {
  SocialProfile,
  SocialFriend,
  SocialFriendsList,
  SocialPost,
  SocialFeed,
  SocialMessage,
  SocialConversation,
  SocialAlbum,
  SocialPhoto,
  SocialVideo,
  SocialEvent,
  SocialGroup,
  OAuthConfig,
  AuthorizationRequest,
  TokenRequest,
  RefreshTokenRequest,
  SocialApiError,
  CursorPagination,
  OffsetPagination,
} from "./types/social";

// Export ZNS constants and helpers
export * from "./constants/zns.constants";

// Export message types (avoiding conflicts with webhook types)
export type {
  BaseMessage,
  TextMessage,
  ImageMessage,
  FileMessage,
  StickerMessage,
  TemplateMessage as MessageTemplateMessage,
  ReactionMessage as MessageReactionMessage,
  Message,
  MessageRecipient,
  SendMessageRequest,
  SendMessageResponse,
  UploadFileResponse,
  MessageStatus,
  MessageEvent,
  ConsultationTextMessage,
  ConsultationImageMessage,
  ConsultationFileMessage,
  ConsultationStickerMessage,
  ConsultationQuoteMessage,
  ConsultationRequestInfoMessage,
  TransactionMessage,

  AnonymousTextMessage,
  AnonymousImageMessage,
  AnonymousFileMessage,
  AnonymousStickerMessage,
  MiniAppMessage,
  ExtendedMessage,
  // New message types from api.md
  AnonymousMessageRecipient,
  AnonymousMessageResponse,
  ReactIcon,
  SenderAction,
  MessageReactionResponse,
  MiniAppMessageRequest,
  MiniAppMessageButton,
  MiniAppMessageResponse,
} from "./types/message";

// Export webhook types (avoiding conflicts with message and group types)
export * from "./types/webhook";

// Export type guards and utilities (selective export to avoid conflicts)
export {
  UserGroupMessageEvent,
  isUserSendGroupTextEvent,
  isUserSendGroupImageEvent,
  isUserSendGroupVideoEvent,
  isUserSendGroupAudioEvent,
  isUserSendGroupFileEvent,
  isUserGroupMessageEvent,
  isOASendTextEvent,
  isOASendImageEvent,
  isOASendFileEvent,
  isOASendStickerEvent,
  isOASendGifEvent,
  isOASendGroupTextEvent,
  isOASendGroupImageEvent,
  isOASendGroupFileEvent,
  isOASendGroupStickerEvent,
  isOASendGroupGifEvent,
  isFromGroup,
  isFromPersonal,
} from "./utils/type-guards";
// Export webhook helper functions
export {
  isUserMessageEvent,
  isGroupMessageEvent,
  isOAToUserMessageEvent,
  isOAToGroupMessageEvent,
  getMessageDirection,
  getWebhookEventAppId,
  getWebhookEventOaId,
  getWebhookEventSenderId,
  getWebhookEventRecipientId,
  getWebhookEventIdentifiers,
} from "./types/webhook";

// Export group types (avoiding conflicts with webhook types)
export type {
  GroupMessage,
  GroupTextMessage,
  GroupImageMessage,
  GroupFileMessage,
  GroupStickerMessage,
  GroupMentionMessage,
  GroupMessageResult,
  GroupInfo as GroupManagementInfo,
  GroupMember,
  GroupMemberList,
  GroupSettings,
  GroupJoinRequest,
  GroupJoinRequestList,
  GroupInvitation,
  GroupActivity,
  GroupActivityList,
  GroupStatistics,
  GroupMessageTemplate,
  GroupMessageSchedule,
  GroupBroadcast,
  GroupPermission,
  GroupWebhookEvent as GroupManagementWebhookEvent,
  GroupApiResponse,
  GroupCreateResponse,
  GroupUpdateResponse,
  GroupDeleteResponse,
  GroupMemberActionResponse,
  GroupCreateRequest,
  GroupCreateResult,
  GroupUpdateRequest,
  GroupAvatarUpdateRequest,
  GroupMemberInviteRequest,
  GroupMemberActionRequest,
  GroupAdminActionRequest,
  GroupDeleteRequest,
  GroupPendingMember,
  GroupQuota,
  GroupQuotaAsset,
  GroupRecentChat,
  GroupConversationMessage,
  GroupsOfOAResponse,
  GroupDetailResponse,
  GroupPendingMembersResponse,
  GroupAcceptPendingMembersRequest,
  GroupAcceptPendingMembersResponse,
  GroupRemoveMembersRequest,
  GroupRemoveMembersResponse,
  GroupMembersResponse,
  GroupQuotaMessageRequest,
  GroupQuotaMessageResponse,
  AllGroupMembersResponse,
  GetAllMembersProgress,
  EnhancedGroupMember,
  AllGroupMembersWithDetailsResponse,
  GetAllMembersWithDetailsProgress,
} from "./types/group";
// Avoid duplicate exports - UserListResponse is already exported from user.ts
export type {
  UserProfile as UserManagementProfile,
  UserList as UserManagementList,
  UserTag,
  UserTagList,
  UserNote,
  UserInteraction,
  UserAnalytics,
  UserSegment,
  UserCustomField,
  UserCustomFieldValue,
  UserBehavior,
  UserJourney,
  UserPreference,
  UserActivity,
  UserExport,
  UserImport,
  UserSearch,
  UserSearchResult,
  BulkUserOperation,
} from "./types/user-management";

// Export clients
export { BaseClient } from "./clients/base-client";
export { ZaloClient } from "./clients/zalo-client";

// Export services
export { AuthService } from "./services/auth.service";
export { OAService } from "./services/oa.service";
// export { MessageService } from "./services/message.service"; // Replaced by specialized message services
export { UserService } from "./services/user.service";
// export { WebhookService } from "./services/webhook.service";
export { ZNSService } from "./services/zns.service";
export {
  GroupMessageService,
  GroupMessageItem,
  MultipleGroupsProgressInfo,
  SendMessageListToMultipleGroupsRequest,
  SendMessageListToMultipleGroupsResponse
} from "./services/group-message.service";
export { GroupManagementService } from "./services/group-management.service";
export { ArticleService } from "./services/article.service";
export { VideoUploadService } from "./services/video-upload.service";

// Message Services - Specialized by message type
export { ConsultationService } from "./services/consultation.service";
export { TransactionService } from "./services/transaction.service";
export { PromotionService } from "./services/promotion.service";
export { GeneralMessageService } from "./services/general-message.service";
export {
  MessageManagementService,
  UploadFileResult,
  UploadImageResult,
  MessageQuotaInfo,
  ConversationMessage,
  Conversation
} from "./services/message-management.service";
export { BroadcastService } from "./services/broadcast.service";
export { PurchaseService } from "./services/purchase.service";

// New services from api.md
export {
  AnonymousMessageService,
  AnonymousTextMessageRequest,
  AnonymousImageMessageRequest,
  AnonymousFileMessageRequest,
  AnonymousStickerMessageRequest,
  AnonymousImageAttachment,
  AnonymousFileAttachment,
  AnonymousStickerAttachment,
} from "./services/anonymous-message.service";
export {
  MessageReactionService,
  MessageReactionRequest,
  ReactionIcon as MessageReactionIconEnum,
} from "./services/message-reaction.service";
export {
  MiniAppMessageService,
  MiniAppSendMessageRequest,
  MiniAppQuotaType,
  QuotaOwnerType,
} from "./services/miniapp-message.service";

// Export main SDK class
export { ZaloSDK } from "./zalo-sdk";

// Export default
export { ZaloSDK as default } from "./zalo-sdk";
