/**
 * Types for Zalo Webhook Events
 * Based on Zalo Official Account Webhook API
 */

// ==================== BASE WEBHOOK TYPES ====================

/**
 * Base webhook event structure
 */
export interface BaseWebhookEvent {
  /** Application ID */
  app_id: string;
  /** User ID for Social API */
  user_id_by_app: string;
  /** Event name */
  event_name: string;
  /** Event timestamp */
  timestamp: string;
}

/**
 * Webhook sender information
 */
export interface WebhookSender {
  /** Sender ID */
  id: string;
}

/**
 * Webhook recipient information
 */
export interface WebhookRecipient {
  /** Recipient ID */
  id: string;
}

/**
 * Webhook follower information (for follow events)
 */
export interface WebhookFollower {
  /** Follower ID */
  id: string;
}

/**
 * Webhook customer information (for shop events)
 */
export interface WebhookCustomer {
  /** Customer ID */
  id: string;
}

/**
 * User submitted information
 */
export interface UserSubmittedInfo {
  /** User address */
  address?: string;
  /** User phone number */
  phone?: string;
  /** User city */
  city?: string;
  /** User district */
  district?: string;
  /** User name */
  name?: string;
  /** User ward */
  ward?: string;
}

/**
 * Webhook user information (for click events)
 */
export interface WebhookUser {
  /** User ID */
  id?: string;
}

/**
 * Message with reaction
 */
export interface ReactionMessage {
  /** Message ID */
  msg_id: string;
  /** Reaction icon */
  react_icon: string;
}

/**
 * Anonymous message with conversation ID
 */
export interface AnonymousMessage extends WebhookBaseMessage {
  /** Conversation ID for anonymous chat */
  conversation_id: string;
}

/**
 * Call information for call events
 */
export interface CallInfo {
  /** Call ID */
  call_id: string;
  /** Call type (AUDIO, VIDEO) */
  call_type: string;
  /** Call initialization time */
  init_time: string;
  /** Total call duration in milliseconds */
  call_duration: string;
  /** Waiting time before call answered */
  waiting_time: string;
  /** Actual talk time */
  talk_time: string;
  /** Call status code */
  status_code: string;
  /** Phone number */
  phone?: string;
}

/**
 * Template message payload
 */
export interface TemplatePayload {
  /** Template checksum */
  checksum: string;
  /** Template link URL */
  link_url: string;
  /** Zalo instant ID */
  zinstant_id: string;
  /** Template text content */
  text: string;
}

/**
 * Template message source
 */
export interface TemplateSource {
  /** Service name */
  service: string;
  /** Application ID */
  app_id: string;
}

/**
 * Template message
 */
export interface TemplateMessage {
  /** Client message ID */
  client_msg_id: string;
  /** Template payload */
  payload: TemplatePayload;
  /** Message source */
  source: TemplateSource;
  /** Message ID */
  msg_id: string;
  /** Is reply flag */
  is_reply: boolean;
}

/**
 * Business card payload
 */
export interface BusinessCardPayload {
  /** Business card thumbnail */
  thumbnail: string;
  /** Business card description (JSON string) */
  description: string;
  /** Business card URL */
  url: string;
}

/**
 * Business card message
 */
export interface BusinessCardMessage extends WebhookBaseMessage {
  /** Client message ID */
  client_msg_id: string;
  /** Business card attachments */
  attachments: Array<
    MessageAttachment & { type: "link"; payload: BusinessCardPayload }
  >;
}

/**
 * User feedback message
 */
export interface FeedbackMessage {
  /** Feedback note */
  note: string;
  /** Rating score */
  rate: number;
  /** Submit time */
  submit_time: string;
  /** Feedback options */
  feedbacks: string[];
  /** Message ID */
  msg_id: string;
  /** Tracking ID */
  tracking_id: string;
}

/**
 * Quota change information
 */
export interface QuotaChange {
  /** Previous quota value */
  prev_value: number;
  /** New quota value */
  new_value: number;
}

/**
 * Tag level change information
 */
export interface TagLevelChange {
  /** Previous tag level */
  prev_value: number;
  /** New tag level */
  new_value: number;
}

/**
 * ZNS delivery message
 */
export interface ZNSDeliveryMessage {
  /** Delivery time */
  delivery_time: string;
  /** Message ID */
  msg_id: string;
  /** Tracking ID */
  tracking_id: string;
}

/**
 * Group information
 */
export interface GroupInfo {
  /** Group ID */
  group_id: string;
  /** Official Account ID */
  oa_id: string;
  /** Application ID */
  app_id: string;
  /** User list (for group events) */
  users?: string[];
}

/**
 * Widget interaction data
 */
export interface WidgetInteractionData {
  /** User ID by OA */
  user_id_by_oa: string;
  /** User external ID */
  user_external_id: string;
  /** Widget URL */
  url: string;
}

/**
 * Widget sync failure data
 */
export interface WidgetSyncFailureData {
  /** Error message */
  message: string;
  /** User ID by OA */
  user_id_by_oa: string;
  /** User external ID */
  user_external_id: string;
}

/**
 * Template status change
 */
export interface TemplateStatusChange {
  /** Previous status */
  prev_status: string;
  /** New status */
  new_status: string;
}

/**
 * Permission revoked data
 */
export interface PermissionRevokedData {
  /** Action performed by (APP or OA) */
  action_by: string;
  /** Revoked timestamp */
  revoked_at: string;
}

/**
 * Extension subscription info
 */
export interface ExtensionSubscriptionInfo {
  /** Valid through date */
  valid_through_date: string;
  /** Duration in months */
  duration_month: string;
  /** Valid start date */
  valid_start_date: string;
}

/**
 * Update user info data
 */
export interface UpdateUserInfoData {
  /** Update method */
  method: string;
}

/**
 * Anonymous message with attachments and conversation ID
 */
export interface AnonymousMessageWithAttachments
  extends WebhookMessageWithAttachments {
  /** Conversation ID for anonymous chat */
  conversation_id: string;
}

// ==================== MESSAGE ATTACHMENT TYPES ====================

/**
 * Location coordinates
 */
export interface LocationCoordinates {
  /** Latitude */
  latitude: string;
  /** Longitude */
  longitude: string;
}

/**
 * Location attachment payload
 */
export interface LocationPayload {
  /** Location coordinates */
  coordinates: LocationCoordinates;
}

/**
 * Image attachment payload
 */
export interface ImagePayload {
  /** Thumbnail URL */
  thumbnail: string;
  /** Full image URL */
  url: string;
}

/**
 * Link attachment payload
 */
export interface LinkPayload {
  /** Link thumbnail URL */
  thumbnail: string;
  /** Link description */
  description: string;
  /** Link URL */
  url: string;
}

/**
 * Sticker attachment payload
 */
export interface StickerPayload {
  /** Sticker ID */
  id: string;
  /** Sticker URL */
  url: string;
}

/**
 * GIF attachment payload
 */
export interface GifPayload {
  /** GIF thumbnail URL */
  thumbnail: string;
  /** GIF URL */
  url: string;
}

/**
 * Audio attachment payload
 */
export interface AudioPayload {
  /** Audio file URL */
  url: string;
}

/**
 * Video attachment payload
 */
export interface VideoPayload {
  /** Video thumbnail URL */
  thumbnail: string;
  /** Video description */
  description: string;
  /** Video file URL */
  url: string;
}

/**
 * File attachment payload
 */
export interface FilePayload {
  /** File download URL */
  url: string;
  /** File size in bytes */
  size: string;
  /** File name */
  name: string;
  /** File checksum */
  checksum: string;
  /** File type/MIME type */
  type: string;
}

/**
 * Enhanced link payload for OA list messages
 */
export interface EnhancedLinkPayload extends LinkPayload {
  /** Link title */
  title: string;
}

/**
 * Union type for all attachment payloads
 */
export type AttachmentPayload =
  | LocationPayload
  | ImagePayload
  | LinkPayload
  | StickerPayload
  | GifPayload
  | AudioPayload
  | VideoPayload
  | FilePayload
  | EnhancedLinkPayload;

/**
 * Message attachment
 */
export interface MessageAttachment {
  /** Attachment payload */
  payload: AttachmentPayload;
  /** Attachment type */
  type:
    | "location"
    | "image"
    | "link"
    | "sticker"
    | "gif"
    | "audio"
    | "video"
    | "file";
}

