/**
 * Helper function to get message direction and target type
 */
export function getMessageDirection(event: WebhookEvent): {
  direction: 'incoming' | 'outgoing' | 'unknown';
  target: 'user' | 'group' | 'unknown';
  description: string;
} {
  if (isUserMessageEvent(event)) {
    return {
      direction: 'incoming',
      target: 'user',
      description: 'Tin nhắn từ người dùng cá nhân gửi tới OA'
    };
  }

  if (isGroupMessageEvent(event)) {
    return {
      direction: 'incoming',
      target: 'group',
      description: 'Tin nhắn từ người dùng trong group'
    };
  }

  if (isOAToUserMessageEvent(event)) {
    return {
      direction: 'outgoing',
      target: 'user',
      description: 'Tin nhắn từ OA gửi tới người dùng cá nhân'
    };
  }

  if (isOAToGroupMessageEvent(event)) {
    return {
      direction: 'outgoing',
      target: 'group',
      description: 'Tin nhắn từ OA gửi tới group'
    };
  }

  return {
    direction: 'unknown',
    target: 'unknown',
    description: 'Loại sự kiện không xác định'
  };
}

export interface WebhookEventIdentifiers {
  oaId: string | null;
  appId: string | null;
  senderId: string | null;
  recipientId: string | null;
}

function readWebhookString(value: unknown): string | null {
  if (typeof value !== "string") {
    return null;
  }

  const normalizedValue = value.trim();
  return normalizedValue.length > 0 ? normalizedValue : null;
}

function readWebhookObjectId(value: unknown): string | null {
  if (!value || typeof value !== "object") {
    return null;
  }

  return readWebhookString((value as { id?: unknown }).id);
}

function hasWebhookEventPrefix(event: WebhookEvent, prefix: string): boolean {
  return event.event_name.startsWith(prefix);
}

export function getWebhookEventAppId(event: WebhookEvent): string | null {
  const directAppId = readWebhookString((event as { app_id?: unknown }).app_id);

  if (directAppId) {
    return directAppId;
  }

  if ("message" in event && event.message && typeof event.message === "object") {
    const messageSource = (event.message as { source?: unknown }).source;

    if (messageSource && typeof messageSource === "object") {
      return readWebhookString(
        (messageSource as { app_id?: unknown }).app_id
      );
    }
  }

  return null;
}

export function getWebhookEventOaId(event: WebhookEvent): string | null {
  const directOaId = readWebhookString((event as { oa_id?: unknown }).oa_id);

  if (directOaId) {
    return directOaId;
  }

  if (hasWebhookEventPrefix(event, "oa_")) {
    return readWebhookObjectId((event as { sender?: unknown }).sender);
  }

  if (
    hasWebhookEventPrefix(event, "user_") ||
    hasWebhookEventPrefix(event, "anonymous_")
  ) {
    return readWebhookObjectId((event as { recipient?: unknown }).recipient);
  }

  return null;
}

export function getWebhookEventSenderId(event: WebhookEvent): string | null {
  const directSenderId = readWebhookObjectId(
    (event as { sender?: unknown }).sender
  );

  if (directSenderId) {
    return directSenderId;
  }

  const fallbackSenderId =
    readWebhookString((event as { user_id?: unknown }).user_id) ??
    readWebhookObjectId((event as { follower?: unknown }).follower) ??
    readWebhookObjectId((event as { customer?: unknown }).customer) ??
    readWebhookObjectId((event as { user?: unknown }).user);

  if (fallbackSenderId) {
    return fallbackSenderId;
  }

  if (hasWebhookEventPrefix(event, "oa_")) {
    return getWebhookEventOaId(event);
  }

  return null;
}

export function getWebhookEventRecipientId(
  event: WebhookEvent
): string | null {
  const directRecipientId = readWebhookObjectId(
    (event as { recipient?: unknown }).recipient
  );

  if (directRecipientId) {
    return directRecipientId;
  }

  if (hasWebhookEventPrefix(event, "oa_")) {
    return readWebhookString((event as { user_id?: unknown }).user_id);
  }

  return getWebhookEventOaId(event);
}

export function getWebhookEventIdentifiers(
  event: WebhookEvent
): WebhookEventIdentifiers {
  return {
    oaId: getWebhookEventOaId(event),
    appId: getWebhookEventAppId(event),
    senderId: getWebhookEventSenderId(event),
    recipientId: getWebhookEventRecipientId(event),
  };
}
