/**
 * Base HTTP client for Zalo API
 */

import axios, {
  AxiosInstance,
  AxiosRequestConfig,
  AxiosResponse,
  AxiosError,
} from "axios";
import FormData from "form-data";
import {
  ZaloSDKConfig,
  ZaloSDKError,
  Logger,
  ConsoleLogger,
  RequestConfig,
} from "../types/common";

/**
 * Base client for making HTTP requests to Zalo API
 */
export class BaseClient {
  protected readonly axios: AxiosInstance;
  protected readonly logger: Logger;
  protected readonly config: Required<ZaloSDKConfig>;

  constructor(config: ZaloSDKConfig) {
    // Set default configuration
    this.config = {
      appId: config.appId,
      appSecret: config.appSecret,
      timeout: config.timeout || 30000,
      debug: config.debug || false,
      apiBaseUrl: config.apiBaseUrl || "https://openapi.zalo.me",
      retry: {
        attempts: config.retry?.attempts || 3,
        delay: config.retry?.delay || 1000,
        ...config.retry,
      },
    };

    this.logger = new ConsoleLogger(this.config.debug);

    // Create axios instance
    this.axios = axios.create({
      baseURL: this.config.apiBaseUrl,
      timeout: this.config.timeout,
      headers: {
        "Content-Type": "application/json",
        "User-Agent": "RedAI-Zalo-SDK/1.0.0",
      },
    });

    this.setupInterceptors();
  }

  /**
   * Setup axios interceptors for logging and error handling
   */
  private setupInterceptors(): void {
    // Request interceptor
    this.axios.interceptors.request.use(
      (config: any) => {
        this.logger.debug(
          `Making ${config.method?.toUpperCase()} request to ${config.url}`,
          {
            headers: this.sanitizeHeaders(config.headers || {}),
            params: config.params,
          }
        );
        return config;
      },
      (error: any) => {
        this.logger.error("Request setup error:", error.message);
        return Promise.reject(error);
      }
    );

    // Response interceptor
    this.axios.interceptors.response.use(
      (response: AxiosResponse) => {
        this.logger.debug(`Received response from ${response.config.url}`, {
          status: response.status,
          data: response.data,
        });
        return response;
      },
      (error: AxiosError) => {
        this.handleAxiosError(error);
        return Promise.reject(error);
      }
    );
  }

  /**
   * Sanitize headers for logging (remove sensitive information)
   */
  private sanitizeHeaders(headers: Record<string, any>): Record<string, any> {
    const sanitized = { ...headers };
    if (sanitized.access_token) {
      sanitized.access_token = "***REDACTED***";
    }
    if (sanitized.secret_key) {
      sanitized.secret_key = "***REDACTED***";
    }
    return sanitized;
  }

  /**
   * Handle axios errors and log them
   */
  private handleAxiosError(error: AxiosError): void {
    if (error.response) {
      this.logger.error(`HTTP ${error.response.status} error:`, {
        url: error.config?.url,
        status: error.response.status,
        statusText: error.response.statusText,
        data: error.response.data,
      });
    } else if (error.request) {
      this.logger.error("No response received:", {
        url: error.config?.url,
        message: error.message,
      });
    } else {
      this.logger.error("Request setup error:", error.message);
    }
  }

  /**
   * Make a GET request
   */
  protected async get<T = any>(
    url: string,
    accessToken?: string,
    params?: Record<string, any>
  ): Promise<T> {
    return this.request<T>({
      method: "GET",
      url,
      headers: accessToken ? { access_token: accessToken } : {},
      params,
    });
  }

  /**
   * Make a POST request
   */
  protected async post<T = any>(
    url: string,
    accessToken?: string,
    data?: any,
    params?: Record<string, any>
  ): Promise<T> {
    return this.request<T>({
      method: "POST",
      url,
      headers: accessToken ? { access_token: accessToken } : {},
      data,
      params,
    });
  }

  /**
   * Make a PUT request
   */
  protected async put<T = any>(
    url: string,
    accessToken?: string,
    data?: any,
    params?: Record<string, any>
  ): Promise<T> {
    return this.request<T>({
      method: "PUT",
      url,
      headers: accessToken ? { access_token: accessToken } : {},
      data,
      params,
    });
  }

  /**
   * Make a DELETE request
   */
  protected async delete<T = any>(
    url: string,
    accessToken?: string,
    params?: Record<string, any>
  ): Promise<T> {
    return this.request<T>({
      method: "DELETE",
      url,
      headers: accessToken ? { access_token: accessToken } : {},
      params,
    });
  }

  /**
   * Upload file using FormData
   */
  protected async uploadFile<T = any>(
    url: string,
    accessToken: string,
    file: Buffer | NodeJS.ReadableStream,
    filename: string,
    additionalFields?: Record<string, any>
  ): Promise<T> {
    const formData = new FormData();
    formData.append("file", file, filename);

    if (additionalFields) {
      Object.entries(additionalFields).forEach(([key, value]) => {
        formData.append(key, value);
      });
    }

    return this.request<T>({
      method: "POST",
      url,
      headers: {
        access_token: accessToken,
        ...formData.getHeaders(), // Let form-data package set Content-Type with proper boundary
      },
      data: formData,
    });
  }

  /**
   * Make a generic HTTP request with retry logic
   */
  protected async request<T = any>(config: RequestConfig): Promise<T> {
    let lastError: Error;

    for (
      let attempt = 1;
      attempt <= (this.config.retry?.attempts || 3);
      attempt++
    ) {
      try {
        const axiosConfig: AxiosRequestConfig = {
          method: config.method,
          url: config.url,
          headers: config.headers,
          params: config.params,
          data: config.data,
          timeout: config.timeout || this.config.timeout,
        };

        const response: AxiosResponse<T> = await this.axios.request(
          axiosConfig
        );

        // Check for Zalo API errors in response
        this.validateZaloResponse(response.data);

        return response.data;
      } catch (error) {
        lastError = error as Error;

        if (
          attempt < (this.config.retry?.attempts || 3) &&
          this.shouldRetry(error as AxiosError)
        ) {
          this.logger.warn(
            `Request failed, retrying (${attempt}/${
              this.config.retry?.attempts || 3
            })...`
          );
          await this.delay((this.config.retry?.delay || 1000) * attempt);
          continue;
        }

        break;
      }
    }

    throw this.createSDKError(lastError!);
  }

  /**
   * Validate Zalo API response for errors
   */
  private validateZaloResponse(data: any): void {
    if (data && typeof data === "object") {
      // Check for standard Zalo error format
      if ("error" in data && data.error !== 0) {
        const errorMessage =
          data.error_description || data.message || "Unknown Zalo API error";
        throw new ZaloSDKError(errorMessage, data.error, data);
      }

      // Check for nested result error format
      if (
        "result" in data &&
        data.result &&
        typeof data.result === "object" &&
        "error" in data.result &&
        data.result.error !== 0
      ) {
        const errorMessage =
          data.result.error_description ||
          data.result.message ||
          "Unknown Zalo API error";
        throw new ZaloSDKError(errorMessage, data.result.error, data.result);
      }
    }
  }

  /**
   * Determine if request should be retried
   */
  private shouldRetry(error: AxiosError): boolean {
    // Retry on network errors or 5xx server errors
    return (
      !error.response ||
      (error.response.status >= 500 && error.response.status < 600)
    );
  }

  /**
   * Create SDK error from axios error
   */
  private createSDKError(error: Error): ZaloSDKError {
    if (error instanceof ZaloSDKError) {
      return error;
    }

    if (error instanceof AxiosError) {
      const response = (error as any).response;
      if (response?.data) {
        const errorCode = response.data.error || response.status;
        const errorMessage =
          response.data.error_description ||
          response.data.message ||
          error.message;
        return new ZaloSDKError(errorMessage, errorCode, response.data);
      }
    }

    return new ZaloSDKError(error.message, -1, error);
  }

  /**
   * Delay execution for specified milliseconds
   */
  private delay(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}
