/**
 * Official Account (OA) service for Zalo API
 */

import { ZaloClient } from '../clients/zalo-client';
import {
  OAInfo,
  MessageQuota,
  QuotaMessageRequest,
  QuotaMessageResponse,
  QuotaAsset,
  OASettings,
  OAStatistics,
  UpdateOAProfileRequest,
  OAVerificationRequest,
  GMFProductType,
  QuotaType,
} from '../types/oa';
import { ZaloResponse, ZaloSDKError } from '../types/common';

/**
 * Official Account service for managing OA information and settings
 */
export class OAService {
  // Zalo API endpoints - organized by functionality
  private readonly endpoints = {
    // OA information
    info: "https://openapi.zalo.me/v2.0/oa/getoa",
    // Quota endpoints
    quota: {
      message: "https://openapi.zalo.me/v3.0/oa/quota/message",
    },
    // Profile management
    profile: {
      update: "https://openapi.zalo.me/v2.0/oa/update",
    },
    // Statistics
    statistics: {
      overview: "https://openapi.zalo.me/v2.0/oa/statistics",
    },
  };

  constructor(private readonly client: ZaloClient) {}

  /**
   * Get Official Account information
   */
  public async getOAInfo(accessToken: string): Promise<OAInfo> {
    try {
      const endpoint = this.endpoints.info;
      const result: ZaloResponse<OAInfo> = await this.client.apiGet(endpoint, accessToken);

      if (result.error !== 0) {
        throw new ZaloSDKError(
          result.message || 'Failed to get OA information',
          result.error,
          result
        );
      }

      if (!result.data) {
        throw new ZaloSDKError('No OA data received', -1);
      }

      return result.data;
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(`Failed to get OA info: ${error.message}`, -1, error);
    }
  }

  /**
   * Get detailed quota message information
   */
  public async getDetailedQuotaMessage(
    accessToken: string,
    request: QuotaMessageRequest
  ): Promise<QuotaAsset[]> {
    try {
      const endpoint = this.endpoints.quota.message;
      const result: QuotaMessageResponse = await this.client.apiPost(endpoint, accessToken, request);

      if (result.error !== 0) {
        throw new ZaloSDKError(
          result.message || 'Failed to get detailed quota message',
          result.error,
          result
        );
      }

      return result.data || [];
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(`Failed to get detailed quota message: ${error.message}`, -1, error);
    }
  }

  /**
   * Get quota for specific product type
   */
  public async getQuotaByProductType(
    accessToken: string,
    productType: 'cs' | 'transaction' | 'gmf10' | 'gmf50' | 'gmf100',
    quotaType?: 'sub_quota' | 'purchase_quota' | 'reward_quota'
  ): Promise<QuotaAsset[]> {
    const request: QuotaMessageRequest = {
      quota_owner: 'OA',
      product_type: productType,
      quota_type: quotaType,
    };

    return this.getDetailedQuotaMessage(accessToken, request);
  }

  /**
   * Get available GMF quota
   */
  public async getGMFQuota(
    accessToken: string,
    gmfType: GMFProductType = GMFProductType.GMF10
  ): Promise<QuotaAsset[]> {
    return this.getQuotaByProductType(accessToken, gmfType);
  }

  /**
   * Get consultation message quota
   */
  public async getConsultationQuota(accessToken: string): Promise<QuotaAsset[]> {
    return this.getQuotaByProductType(accessToken, 'cs');
  }

  /**
   * Get transaction message quota
   */
  public async getTransactionQuota(accessToken: string): Promise<QuotaAsset[]> {
    return this.getQuotaByProductType(accessToken, 'transaction');
  }

  /**
   * Update OA profile information
   */
  public async updateOAProfile(
    accessToken: string,
    profileData: UpdateOAProfileRequest
  ): Promise<boolean> {
    try {
      // Note: This endpoint might not be available in all Zalo API versions
      // This is a placeholder implementation
      const endpoint = this.endpoints.profile.update;
      const result = await this.client.apiPost(endpoint, accessToken, profileData);

      if (result.error !== 0) {
        throw new ZaloSDKError(
          result.message || 'Failed to update OA profile',
          result.error,
          result
        );
      }

      return true;
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(`Failed to update OA profile: ${error.message}`, -1, error);
    }
  }

  /**
   * Get OA statistics (if available)
   */
  public async getOAStatistics(accessToken: string): Promise<OAStatistics> {
    try {
      // Note: This endpoint might not be available in all Zalo API versions
      // This is a placeholder implementation
      const endpoint = this.endpoints.statistics.overview;
      const result = await this.client.apiGet(endpoint, accessToken);

      if (result.error !== 0) {
        throw new ZaloSDKError(
          result.message || 'Failed to get OA statistics',
          result.error,
          result
        );
      }

      return result.data || {
        total_followers: 0,
        new_followers_today: 0,
        messages_sent_today: 0,
        messages_received_today: 0,
      };
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(`Failed to get OA statistics: ${error.message}`, -1, error);
    }
  }

  /**
   * Lấy thông tin quota tổng quan cho tin nhắn (tổng số asset và số còn khả dụng)
   * Lưu ý: Zalo hiện cung cấp API chi tiết qua endpoint quota/message theo asset.
   * Hàm này tổng hợp đơn giản để trả về cấu trúc MessageQuota phục vụ SDK.
   */
  public async getMessageQuota(accessToken: string): Promise<MessageQuota> {
    try {
      // Gọi endpoint quota/message không chỉ định product_type để lấy toàn bộ asset
      const request: QuotaMessageRequest = {
        quota_owner: 'OA',
      };
      const assets = await this.getDetailedQuotaMessage(accessToken, request);

      // Đếm tổng asset và số asset còn khả dụng
      const totalAssets = assets.length;
      const availableAssets = assets.filter((a) => a.status === 'available')
        .length;

      // Trả về dạng MessageQuota tối giản
      const quota: MessageQuota = {
        // Sử dụng tổng số asset làm daily_quota (ước lượng theo asset)
        daily_quota: totalAssets,
        // Số còn lại là số asset đang ở trạng thái available
        remaining_quota: availableAssets,
        // Quota type tổng hợp vì có thể gồm nhiều loại
        quota_type: 'mixed',
        // Không có reset_time từ API asset -> trả 0
        reset_time: 0,
      };

      return quota;
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(
        `Failed to get message quota: ${((error as unknown) as Error).message}`,
        -1,
        error
      );
    }
  }

  /**
   * Check if OA has sufficient quota for message type
   */
  public async hasQuotaForMessageType(
    accessToken: string,
    messageType: 'cs' | 'transaction' | 'promotion',
    requiredCount: number = 1
  ): Promise<boolean> {
    try {
      let productType: 'cs' | 'transaction';
      
      if (messageType === 'promotion') {
        // Promotion messages might use different quota logic
        return true; // Placeholder
      } else {
        productType = messageType;
      }

      const quotaAssets = await this.getQuotaByProductType(accessToken, productType);
      
      // Check if there are available assets
      const availableAssets = quotaAssets.filter(asset => asset.status === 'available');
      
      if (availableAssets.length === 0) {
        return false;
      }

      // For simplicity, assume each available asset can handle the required count
      return true;
    } catch (error) {
      // If we can't check quota, assume it's available to avoid blocking
      return true;
    }
  }

  /**
   * Get quota summary for all message types
   */
  public async getQuotaSummary(accessToken: string): Promise<{
    consultation: QuotaAsset[];
    transaction: QuotaAsset[];
    gmf10: QuotaAsset[];
    gmf50: QuotaAsset[];
    gmf100: QuotaAsset[];
  }> {
    try {
      const [consultation, transaction, gmf10, gmf50, gmf100] = await Promise.all([
        this.getConsultationQuota(accessToken),
        this.getTransactionQuota(accessToken),
        this.getGMFQuota(accessToken, GMFProductType.GMF10),
        this.getGMFQuota(accessToken, GMFProductType.GMF50),
        this.getGMFQuota(accessToken, GMFProductType.GMF100),
      ]);

      return {
        consultation,
        transaction,
        gmf10,
        gmf50,
        gmf100,
      };
    } catch (error) {
      if (error instanceof ZaloSDKError) {
        throw error;
      }
      throw new ZaloSDKError(`Failed to get quota summary: ${error.message}`, -1, error);
    }
  }

  /**
   * Validate OA access token by getting OA info
   */
  public async validateOAToken(accessToken: string): Promise<boolean> {
    try {
      await this.getOAInfo(accessToken);
      return true;
    } catch (error) {
      return false;
    }
  }
}
